const MapTanzania = ({ element, active, highlighted, width, onClick, onChange }) => {
  return (
    <ElementWrapper
      element={element}
      onClick={onClick}
      onChange={onChange}
      maxWidth={width}
      active={active}
      highlighted={highlighted}
      resizeHandles={['e']}
      editable
      fit
    >
      <MapTanzaniaContent element={element} />
    </ElementWrapper>
  );
};

export const MapTanzaniaPresent = ({ element }) => {
  return <MapTanzaniaContent element={element} />;
};

